import { statusFor,setItemStatus,purchaseAll,sortedItems,shoppingComplete,plateAnchors,freshState,validateRecipe,safeImage } from './core/meal-state.js';
import * as cloud from './core/cloud.js';
import { actionError } from './core/action-errors.js';
import { memberStage,mailboxUrl } from './core/registration.js';
import { beginCooking,normalizeCooking,moveTicket,placeTicket,serveTicket,allServed,finishCooking } from './core/cooking.js';
import { cookingView,cookingHistory } from './features/cooking-view.js';
import { compressMealPhoto } from './core/meal-photo.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=['zh','en'].includes(new URLSearchParams(location.search).get('lang'))?new URLSearchParams(location.search).get('lang'):read('shiguang-language','zh'),profile=null,publicRecipes=[],counts={},busy=false,cloudReady=false,syncTimer,installPrompt=null,activeKey=cloud.currentSession()?.user?.id||'guest';
let data=activeKey==='guest'?freshState():read('little-table:'+activeKey,null);
if(activeKey!=='guest'){profile=read('little-table-profile:'+activeKey,null);if(!data)data=freshState();}
if(!data){data=freshState(read('shiguang-saved',seeds.filter(r=>r.featured).map(r=>r.id)));data.custom=read('shiguang-recipes',[]);const oldPlan=read('shiguang-meal-plan',{});data.plan=oldPlan.selected||oldPlan;}
data=normalizeData(data);
function pendingEmail(){try{return sessionStorage.getItem('little-table-verification-email')||'';}catch{return '';}}
const ui={verificationEmail:pendingEmail(),query:'',purpose:'全部',cuisine:'全部',category:'全部',sort:'popular',matching:false,pantry:'',extra:2,menu:'全部',editor:null,editorImage:null,editorIcon:null,adminUsers:[],adminPosts:[],cloudMessage:'',lastDetail:null};
let memberVerified=false,catalogLoaded=false,accountChecking=!!cloud.currentSession();
const L=(zh,en)=>lang==='en'?en:zh;
const tr=s=>lang==='en'?english(String(s)):String(s);
const artAssets=visualAssets.filter(a=>a.kind==='Dish');
const publicViews=new Set(['home','login','register','forgot','reset-password','verify-email','rights']);
const publicActions=new Set(['language','close','logout','refresh-account','install','install-help']);
function canUseMembers(){return catalogLoaded&&(!cloud.currentSession()||(memberVerified&&memberStage(profile,cloud.currentSession()?.user)==='approved'));}
function memberGate(){const stage=memberStage(profile,cloud.currentSession()?.user);const titleText=accountChecking?L('正在核验账号','Checking your account'):!cloud.currentSession()?L('登录后使用小饭桌','Log in to use Little Table'):stage==='verify-email'?L('请先验证邮箱','Verify your email first'):stage==='pending'?L('等待管理员审核','Waiting for approval'):stage==='suspended'?L('账号已停用','Account suspended'):stage==='rejected'?L('申请未通过审核','Request not approved'):L('暂时无法验证账号','Could not verify your account');return '<section class="auth-shell"><div class="panel verification-panel">'+art({id:'jiangsu-rice'},150)+'<h1>'+titleText+'</h1><p>'+L('仅限邮箱已验证、管理员审核通过的账号使用。','Access requires a verified email address and administrator approval.')+'</p>'+(!cloud.currentSession()?link(L('登录','Log in'),'login')+link(L('注册申请','Request access'),'register','secondary'):stage==='verify-email'?link(L('去验证邮箱','Verify email'),'verify-email'):action(L('刷新账号状态','Refresh account'),'refresh-account','','secondary'))+(cloud.currentSession()?action(L('退出登录','Log out'),'logout','','quiet'):'')+'</div></section>';}
function rightsView(){return '<section class="form-shell"><h1 class="page-title">'+L('创作与使用说明','Creative work and usage')+'</h1><div class="panel stack"><h2>Zoya Yin · 小饭桌 / Little Table</h2><p>'+L('界面设计、原创图形与代码表达，请勿未经许可复制、转载或用于商业项目。依法允许的使用不受影响。','Please obtain permission before copying, republishing or commercially reusing original interface designs, graphics or code. Legally permitted uses remain unaffected.')+'</p><p>'+L('收录食谱及用户投稿的权利归各自权利人；用户上传的私人食谱和照片不会因此转让权利。','Rights in collected recipes and contributions remain with their respective owners. Uploading personal recipes or photos does not transfer ownership.')+'</p>'+link(L('返回首页','Back to home'),'home','secondary')+'</div></section>';}
async function loadMemberCatalog(){const response=await fetch('/api/little-table/catalog',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!response.ok){const error=new Error('MEMBER_ACCESS_REQUIRED');error.status=response.status;throw error;}const value=await response.json();if(!Array.isArray(value.recipes)||!value.recipes.length)throw Error('CATALOG_UNAVAILABLE');seeds=value.recipes;newRecipes=[];kitchen=value.kitchen;setTranslations(value.translations||[]);catalogLoaded=true;}
function recipeList(){const map=new Map([...seeds,...newRecipes,...publicRecipes,...data.custom].map(r=>[r.id,r]));return [...map.values()];}
function recipe(id){return recipeList().find(r=>r.id===id);}
function title(r){return lang==='en'?(r.en?.title||tr(r.title)):r.title;}
function localized(r,key){return lang==='en'?(r.en?.[key]||r[key]?.map?.(tr)||tr(r[key]||'')):r[key];}
function normalizeData(d){const f=freshState();if(!d||typeof d!=='object')return f;for(const key of ['custom','saved','records','submissions'])if(Array.isArray(d[key]))f[key]=d[key];for(const key of ['plan','checks','prices'])if(d[key]&&typeof d[key]==='object'&&!Array.isArray(d[key]))f[key]=d[key];f.journey=d.journey||null;f.cooking=normalizeCooking(d.cooking);f.custom=f.custom.filter(r=>{try{validateRecipe(r);return typeof r.id==='string';}catch{return false;}});return f;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3600);}
function persist(){if(activeKey==='guest')return;if(!write('little-table:'+activeKey,data))toast(L('保存失败，请导出备份','Could not save. Please export a backup.'));if(activeKey!=='guest')write('little-table-dirty:'+activeKey,true);if(cloudReady&&profile?.status==='approved') {clearTimeout(syncTimer);syncTimer=setTimeout(syncCloud,600);}}
let syncing=false,syncAgain=false;
async function syncCloud(){if(syncing){syncAgain=true;return;}if(!cloudReady||profile?.status!=='approved')return;syncing=true;const owner=activeKey;try{await cloud.savePrivate(structuredClone(data));if(!syncAgain)write('little-table-dirty:'+owner,false);ui.cloudMessage=L('已同步','Synced');}catch{ui.cloudMessage=L('暂未同步，本机已保存','Not synced; saved on this device');}finally{syncing=false;if(syncAgain){syncAgain=false;syncTimer=setTimeout(syncCloud,500);}}}
function navigate(route){if(location.hash==='#'+route)render();else location.hash=route;}
function getRoute(){let [view='home',id]=location.hash.slice(1).split('/');if(!view)view='home';return {view,id:decodeURIComponent(id||'')};}
function action(label,name,id='',style='primary',extra=''){return `<button class="button ${style}" data-action="${name}" data-id="${esc(id)}" ${extra}>${esc(label)}</button>`;}
function link(label,to,style='primary'){return `<a class="button ${style}" href="#${esc(to)}">${esc(label)}</a>`;}
function assetFor(r){const id=r.icon||r.id;return visualAssets.find(a=>a.kind==='Dish'&&a.id===id)||visualAssets.find(a=>a.id===({蔬菜:'home-spinach',鸡肉:'fav-teriyaki',牛肉:'hunan-beef',鱼虾:'zhejiang-shrimp',蛋类:'s1',豆制品:'sichuan-tofu',面食:'s3',米饭:'jiangsu-rice'}[r.category]||'fav-sweet-sour-ribs'));}
function art(r,size=180){const a=assetFor(r);return `<div class="art" style="--default-size:${Number(size)}px"><img width="200" height="200" src="${esc(a.path)}" alt="" loading="lazy"></div>`;}
function image(r){const photo=r.custom&&safeImage(r.image);return photo?`<img class="photo-cover" src="${esc(photo)}" alt="${esc(title(r))}">`:art(r,240);}
function ingredientArt(name){let a=visualAssets.find(a=>a.kind==='Ingredient'&&a.name===name);if(!a){const aliases={'意大利面（干）':'意大利面','大米（干）':'米饭','去皮鸡胸肉':'鸡胸肉','北豆腐':'豆腐','低脂牛奶':'低脂牛奶','食用油':'橄榄油','鸡蛋清':'蛋清'};a=visualAssets.find(a=>a.kind==='Ingredient'&&(a.name===aliases[name]||norm(a.name)===norm(name)));}return a?`<div class="art"><img width="200" height="200" src="${esc(a.path)}" alt="" loading="lazy"></div>`:`<span class="ingredient-fallback" aria-hidden="true">${esc(name.slice(0,1))}</span>`;}
function observeArt(){assetObserver.disconnect();document.querySelectorAll('.art').forEach(n=>assetObserver.observe(n));}
const assetObserver=new ResizeObserver(entries=>{for(const e of entries)e.target.style.setProperty('--asset-scale',e.contentRect.width/200);});
function header(view){const links=[['home',L('首页','Home')],['library',L('食谱库','Recipes')],['today',L('今天吃什么','Today’s table')],['shopping',L('买菜清单','Groceries')],['cooking',L('做菜','Cooking')],['profile',L('我的','My kitchen')]];
 $('#header').innerHTML=`<a class="brand" href="#home">${L('小饭桌','Little Table')}<small>${lang==='zh'?'LITTLE TABLE':'小饭桌'}</small></a><nav class="desktop-nav">${links.map(([key,label])=>`<a href="#${key}" class="${view===key?'active':''}" ${view===key?'aria-current="page"':''}>${esc(label)}</a>`).join('')}</nav><div class="header-tools"><button class="language" data-action="language" aria-label="${L('切换到英文','Switch to Chinese')}">中 / EN</button>${installPrompt?action(L('安装','Install'),'install','','secondary install-label'):''}${link(profile?.display_name||L('登录 / 注册','Log in'),profile?'profile':'login','secondary')}</div>`;
 const paths={home:'M3 11 12 3l9 8v10h-6v-7H9v7H3z',library:'M4 4h16v17H4zM8 8h8M8 12h8M8 16h5',today:'M12 3v18M3 12h18',shopping:'M5 12 10 18 20 5',profile:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 22v-3a8 8 0 0 1 16 0v3'};
 $('#bottom').innerHTML=links.filter(([key])=>key!=='cooking').map(([key,label])=>`<a href="#${key}" class="${view===key||view==='history'&&key==='profile'?'active':''}" ${view===key?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[key]}"></path></svg><span>${esc(key==='today'?L('点菜','Table'):key==='shopping'?L('清单','List'):key==='profile'?L('我的','Me'):label)}</span></a>`).join('');
 let notice=$('#copyright');if(notice)notice.innerHTML='<a href="#rights">© 2026 Zoya Yin · 小饭桌 / Little Table</a>';
 document.documentElement.lang=lang==='en'?'en':'zh-CN';document.title=L('小饭桌 · 好好吃饭','Little Table · Good food, every day');
}
function home(){const ids=['fav-sweet-sour-ribs','fav-tuscan','s1','home-spinach','jiangsu-rice','zhejiang-shrimp'];return `<section class="home-landing"><div class="food-parade">${ids.map(id=>`<div>${art(recipe(id)||{id},190)}</div>`).join('')}</div><div class="home-intro"><h1>${L('每一顿，都值得期待。','A little joy in every meal.')}</h1><div class="hero-links">${link(L('开始好好吃饭 →','Let’s cook something good →'),'today')}${link(L('注册申请','Request access'),'register','quiet')}</div></div></section>`;}
function chipRows(list,key,current){return `<div class="chips" role="group" aria-label="${esc(key)}">${list.map(s=>`<button class="chip ${s===current?'active':''}" data-filter="${key}" data-value="${esc(s)}" aria-pressed="${s===current}">${esc(tr(s))}</button>`).join('')}</div>`;}
function filteredRecipes(){const q=ui.query.trim().toLowerCase();let rows=recipeList().filter(r=>!r.custom||r.public).filter(r=>(ui.purpose==='全部'||r.tags?.includes(ui.purpose))&&(ui.cuisine==='全部'||r.cuisine===ui.cuisine)&&matchesCategory(r,ui.category)&&(!q||[r.title,title(r),...(r.ingredients||[]),...(r.en?.ingredients||[])].join(' ').toLowerCase().includes(q)));if(ui.matching){const stock=ui.pantry.split(/[,，、\n]/).map(norm).filter(Boolean);rows=rows.filter(r=>stock.length&&missing(r,stock).length<=ui.extra&&missing(r,stock).length<groceryForRecipe(r).length).sort((a,b)=>missing(a,stock).length-missing(b,stock).length);}else rows.sort(ui.sort==='latest'?(a,b)=>String(b.createdAt||'2026-10-01').localeCompare(String(a.createdAt||'2026-10-01')):(a,b)=>(counts[b.id]||0)-(counts[a.id]||0));return rows;}
const basics=new Set(['盐','食用油','油','清水','水','橄榄油','生抽','老抽','料酒','白糖','黑胡椒','白胡椒','香醋','白醋','蚝油','生姜','大蒜','小葱','白芝麻']);
function groceryForRecipe(r){return buildShoppingList([r],{[r.id]:1},kitchen).filter(i=>i.group!=='equipment'&&!basics.has(i.name));}
function missing(r,stock){return [...new Set(groceryForRecipe(r).map(i=>i.name))].filter(n=>!stock.includes(norm(n)));}
function cards(rows){if(!rows.length)return `<div class="empty">${L('没有找到食谱','No recipes found')}</div>`;return rows.map(r=>`<article class="recipe-card"><button class="save-button" data-action="save" data-id="${esc(r.id)}" aria-label="${esc(data.saved.includes(r.id)?L('取消收藏','Unsave'):L('收藏','Save'))}" aria-pressed="${data.saved.includes(r.id)}">${data.saved.includes(r.id)?'♥':'♡'}</button><a href="#recipe/${encodeURIComponent(r.id)}"><div class="card-visual">${image(r)}<span class="badge">${esc(r.custom?L('个人创建','My creation'):ui.purpose==='增肌减脂'?L('健身版','Fitness'):r.contributor?L('贡献者 ','By ')+r.contributor:tr(r.cuisine))}</span></div><div class="card-copy"><h3>${esc(title(r))}</h3><div class="card-meta">${r.time} ${L('分钟','min')} · ${r.servings||2}${L('人份',' servings')}${r.contributor?' · '+esc(r.contributor):''}</div>${ui.purpose==='增肌减脂'&&r.nutrition?`<div class="nutrition">≈${r.nutrition.kcal} kcal · ${L('蛋白质','Protein ')}${r.nutrition.protein}g</div>`:`<small class="card-meta">${Number(counts[r.id]||0)} ${L('人添加','saves')}</small>`}</div></a>${ui.matching?`<p class="match-result">${esc(missing(r,ui.pantry.split(/[,，、\n]/).map(norm)).join(' / ')||L('现有食材就能做','Ready with what you have'))}</p>`:''}</article>`).join('');}
function library(){return `<section><div class="library-heading"><h1>${L('今天，想吃点什么？','What’s cooking today?')}</h1>${link(L('＋ 创建食谱','＋ Create recipe'),'create','secondary')}</div><label class="search-box"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="${L('搜索食谱或食材','Search recipes or ingredients')}" value="${esc(ui.query)}" aria-label="${L('搜索食谱或食材','Search recipes or ingredients')}"><button data-action="matching" aria-expanded="${ui.matching}" class="small-button">${L('剩余食材','My ingredients')}</button></label>${ui.matching?`<div class="match-tools"><div class="row"><input id="pantry" placeholder="${L('例如：鸡蛋、番茄','e.g. eggs, tomatoes')}" value="${esc(ui.pantry)}"><label>${L('可补充','Allow extra')} <select id="extra">${[0,1,2,3,4,5,10].map(n=>`<option value="${n}" ${n===ui.extra?'selected':''}>${n}</option>`).join('')}</select></label></div></div>`:''}<div class="filters">${chipRows(['全部','增肌减脂','早饭'],'purpose',ui.purpose)}${chipRows(cuisines,'cuisine',ui.cuisine)}<div class="row"><span class="filter-label">${L('主要食材','Ingredients')}</span>${chipRows(categories,'category',ui.category)}</div></div><div class="count-sort"><small id="recipe-count"></small><select id="sort" aria-label="${L('食谱排序','Sort recipes')}"><option value="popular" ${ui.sort==='popular'?'selected':''}>${L('添加最多','Most saved')}</option><option value="latest" ${ui.sort==='latest'?'selected':''}>${L('最新','Newest')}</option></select></div><div id="recipe-grid" class="recipe-grid ${ui.purpose!=='全部'?'purpose-grid':''}"></div></section>`;}
function updateCards(){const rows=filteredRecipes();$('#recipe-grid').innerHTML=cards(rows);$('#recipe-count').textContent=rows.length+L(' 道食谱',' recipes');observeArt();}
function priceText(id){const p=data.prices[id];return p?new Intl.NumberFormat(lang==='en'?'en-GB':'zh-CN',{style:'currency',currency:p.currency||'CNY'}).format(p.value):'';}
function privateRecipes(){return recipeList().filter(r=>r.custom||data.saved.includes(r.id));}
function planned(){return Object.entries(data.plan).filter(([id,n])=>recipe(id)&&Number(n)>0).map(([id,n])=>({...recipe(id),multiplier:Number(n)}));}
function today(){const rows=privateRecipes().filter(r=>ui.menu==='全部'||r.cuisine===ui.menu);const selected=planned(),display=selected.slice(0,10),anchors=plateAnchors(display.length);return `<section>${cookingResume()}<h1 class="page-title">${L('今天，摆一桌喜欢的。','Set a table you’ll love.')}</h1><div class="random-tools"><label>${L('来几道','Dishes')} <select id="random-count">${[1,2,3,4].map(n=>`<option ${n===2?'selected':''}>${n}</option>`).join('')}</select></label><button data-action="random" class="small-button">✳ ${L('给我一点灵感','Surprise me')}</button>${selected.length?action(L('清空','Clear'),'clear-plan','','quiet small-button'):''}</div><div class="planner"><section class="panel menu-panel"><div class="row between"><h2>${L('私房菜单','Private menu')}</h2><a class="small-button" href="#library">${L('探索食谱 ↗','Explore recipes ↗')}</a></div>${chipRows(['全部','家常菜','创意菜','意大利菜'],'menu',ui.menu)}<div class="menu-list">${rows.map(r=>`<div class="menu-item ${data.plan[r.id]?'selected':''}">${art(r,66)}<div class="menu-info"><a href="#recipe/${encodeURIComponent(r.id)}">${esc(title(r))}</a><small>${r.custom?L('个人创建','My creation'):tr(r.cuisine)} · ${r.time}${L('分钟',' min')}${priceText(r.id)?' · <span class="price-tag">'+esc(priceText(r.id))+'</span>':''}</small></div><button class="round-action" data-action="plan" data-id="${esc(r.id)}" aria-label="${esc((data.plan[r.id]?L('移除 ','Remove '):L('添加 ','Add '))+title(r))}" aria-pressed="${!!data.plan[r.id]}">${data.plan[r.id]?'✓':'＋'}</button></div>`).join('')||`<div class="empty">${L('先收藏喜欢的菜','Save a few favourites first')}<br><br>${link(L('探索食谱','Explore recipes'),'library','secondary')}</div>`}</div></section><section class="table-panel"><div class="row between"><h2>${L('我的餐桌','My table')}</h2><span class="selection-count">${L('已选 ','Selected ')}${selected.length}${L(' 道','')}</span></div><div class="tabletop" aria-label="${L('餐桌','Dining table')}">${display.map((r,i)=>`<a class="plated" href="#recipe/${encodeURIComponent(r.id)}" aria-label="${esc(title(r))}" style="left:${anchors[i][0]*100}%;top:${anchors[i][1]*100}%;--plate-size:${({S:118,M:140,L:162}[r.size||assetFor(r).size]||140)/736*100}%">${art(r)}</a>`).join('')}</div><div class="table-footer">${link(L('生成买菜清单 →','Make grocery list →'),'shopping')}</div></section></div><div class="planner-cta">${link(L('生成买菜清单 →','Make grocery list →'),'shopping')}</div></section>`;}
function shoppingItems(){return buildShoppingList(recipeList(),data.plan,kitchen).filter(i=>i.group!=='equipment'&&!['水','清水'].includes(i.name));}
function isBasic(item){return basics.has(item.name)||(['seasoning'].includes(item.group)&&!['沙茶酱','花生酱','郫县豆瓣酱','豆豉','番茄膏'].includes(item.name));}
function listItems(){return shoppingItems().filter(i=>!isBasic(i));}
function shopping(){const all=listItems(),ordered=sortedItems(all,data.checks),nonOwned=all.filter(i=>statusFor(i,data.checks)!=='owned'),bulk=nonOwned.length>0&&nonOwned.every(i=>statusFor(i,data.checks)==='bought'),done=planned().length>0&&(!all.length||shoppingComplete(all,data.checks));return `<section>${cookingResume()}<h1 class="page-title">${L('买菜清单','Grocery list')}</h1><div class="shopping-layout"><aside class="cart-panel"><h2>${L('购物车','My cart')}</h2><div class="cart-stage"><img class="cart-svg vertical" width="200" height="240" src="assets/ui/ui/shopping-cart-top-vertical.svg" alt="${L('俯视购物车','Shopping cart, top view')}"><img class="cart-svg horizontal" width="240" height="200" src="assets/ui/ui/shopping-cart-top-horizontal.svg" alt=""><div class="cart-contents">${all.map((item,index)=>{const status=statusFor(item,data.checks);if(status==='owned')return '';const slot=index%9,col=slot%3,row=Math.floor(slot/3),layer=Math.floor(index/9);return `<div class="cart-item ${status==='pending'?'ghost':''}" title="${esc(tr(item.name))}" style="--x:${14.5+col*21.8+(row===2?4:0)+layer*1.2}%;--y:${Math.max(8,15.7+row*20.9-layer*2)}%;--mx:${24.3+col*17+(row===2?2:0)+layer}%;--my:${Math.max(12,20+row*17.9-layer*2)}%;--z:${status==='bought'?100+index:index};--tilt:${index%2?4:-5}deg">${ingredientArt(item.name)}</div>`;}).join('')}</div></div></aside><div><div class="portion-strip">${planned().map(r=>`<label>${esc(title(r))}<input data-portion="${esc(r.id)}" type="number" min="0.5" max="20" step="0.5" value="${r.multiplier}" aria-label="${L('份量倍数','Serving multiplier')}"> × ${r.servings||2}${L('人份',' servings')}</label>`).join('')}</div><section class="panel checklist"><div class="row between"><h2>${L('食材','Ingredients')}</h2><label class="bulk"><input id="bulk" type="checkbox" ${bulk?'checked':''} ${!all.length?'disabled':''}>${bulk?L('取消全选','Uncheck all'):L('全选','Check all')}</label></div>${ordered.map(item=>{const s=statusFor(item,data.checks);return `<div class="grocery-row ${s}"><input type="checkbox" class="grocery-check" data-check="${esc(item.id)}" ${s==='bought'?'checked':''} aria-label="${esc(L('已买 ','Purchased ')+tr(item.name))}">${ingredientArt(item.name)}<span class="grocery-name">${esc(tr(item.name))}</span><span class="grocery-amount">${esc(tr(item.amount))}</span><button class="owned-action" data-owned="${esc(item.id)}">${s==='owned'?L('撤销','Undo'):L('已有','Have it')}</button></div>`;}).join('')||`<div class="empty">${L('先安排今天的菜单','Choose today’s dishes first')}<br><br>${link(L('去点菜','Choose dishes'),'today','secondary')}</div>`}<details class="pantry"><summary><span>✓ ${L('常用调料','Pantry staples')}</span><span>${L('查看 ›','View ›')}</span></summary><p>${shoppingItems().filter(isBasic).map(i=>esc(tr(i.name))+' '+esc(tr(i.amount))).join(' / ')||L('盐、油、酱油','Salt, oil, soy sauce')}</p></details></section><div class="shopping-footer">${action(cookingActive()?L('继续做菜 →','Continue cooking →'):L('开始做菜 →','Start cooking →'),'complete','','primary',done||cookingActive()?'':'disabled')}</div><div class="maps"><a id="market-map" target="_blank" rel="noopener noreferrer">${L('附近菜市场 ↗','Nearby markets ↗')}</a><a id="supermarket-map" target="_blank" rel="noopener noreferrer">${L('附近超市 ↗','Nearby supermarkets ↗')}</a><select id="map-provider" aria-label="${L('地图服务','Map provider')}"><option value="baidu" ${read('little-table-map',lang==='zh'?'baidu':'google')==='baidu'?'selected':''}>${L('百度地图','Baidu Maps')}</option><option value="google" ${read('little-table-map',lang==='zh'?'baidu':'google')==='google'?'selected':''}>Google Maps</option></select></div></div></div></section>`;}
function updateMapLinks(){const provider=$('#map-provider')?.value||'google';for(const [id,type]of [['market-map','market'],['supermarket-map','supermarket']]){const query=provider==='baidu'?(type==='market'?'附近菜市场':'附近超市'):(type==='market'?'farmers market near me':'supermarket near me');$('#'+id).href=provider==='baidu'?'https://map.baidu.com/search/'+encodeURIComponent(query):'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(query);}}
function detail(r){if(!r)return `<div class="empty">${L('食谱不存在','Recipe not found')}</div>`;const saved=data.saved.includes(r.id)||r.custom;return `<div class="detail-layout"><div class="detail-hero">${image(r)}</div><article class="detail-copy"><div><small>${esc(tr(r.cuisine))} / ${r.time} ${L('分钟','min')} / ${r.servings||2}${L('人份',' servings')}</small><h1>${esc(title(r))}</h1></div>${r.custom?'<span class="chip active">'+L('个人创建','My creation')+'</span>':''}${r.contributor?'<small>'+L('贡献者 ','Contributed by ')+esc(r.contributor)+'</small>':''}${r.nutrition?`<div class="nutrition-box"><strong>≈ ${r.nutrition.kcal} kcal · ${L('蛋白质','Protein ')} ${r.nutrition.protein}g</strong><small>${L('每份估算','Estimated per serving')}${r.nutrition.oil!==undefined?' · '+L('用油 ','Oil ')+r.nutrition.oil+'g':''}</small></div>`:''}<div class="row wrap">${action(saved?L('已收藏 ✓','Saved ✓'):L('加入私房菜单 ＋','Save to private menu ＋'),'save',r.id,'secondary')}${action(L('摆上餐桌 ＋','Add to table ＋'),'add-table',r.id)}${saved?action(priceText(r.id)||L('记录价格','Record cost'),'price',r.id,'quiet'):''}</div><section class="detail-section"><h2>${L('食材','Ingredients')}</h2><ul>${(localized(r,'ingredients')||[]).map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></section><section class="detail-section"><h2>${L('做法','Method')}</h2><ol>${(localized(r,'steps')||[]).map(x=>'<li>'+esc(x)+'</li>').join('')}</ol></section>${r.note?`<small>${esc(localized(r,'note')||'')}</small>`:''}<div class="toolbar">${r.custom?link(L('编辑食谱','Edit recipe'),'edit/'+encodeURIComponent(r.id),'secondary'):''}${r.custom?action(L('投稿','Submit recipe'),'submit-recipe',r.id,'secondary'):''}${r.custom?action(L('删除','Delete'),'delete-recipe',r.id,'quiet danger'):''}${link(L('探索食谱 ↗','Explore recipes ↗'),'library','quiet')}</div></article></div>`;}
function accountNotice(){const stage=memberStage(profile,cloud.currentSession()?.user);if(!stage||stage==='approved')return '';const copy=stage==='verify-email'?L('请先到邮箱完成验证。','Please verify your email address first.'):stage==='pending'?L('邮箱已验证，等待管理员审核。','Email verified. Waiting for administrator approval.'):stage==='rejected'?L('注册申请未通过审核。','Your registration request was not approved.'):L('账号已停用。','Your account is suspended.');return '<div class="status-banner" role="status">'+copy+'</div>';}
function verifyEmailView(){const address=ui.verificationEmail,url=mailboxUrl(address);return '<section class="auth-shell"><div class="panel verification-panel">'+art(recipe('jiangsu-rice')||{id:'jiangsu-rice'},150)+'<h1>'+L('请到邮箱验证','Verify your email')+'</h1>'+(address?'<p class="verification-address">'+esc(address)+'</p>':'')+'<p>'+L('请打开注册邮件，点击其中的验证链接。','Open the registration email and click its verification link.')+'</p><small>'+L('没有收到？请检查垃圾邮件。','Cannot find it? Check your spam folder.')+'</small>'+(url?'<a class="button primary" target="_blank" rel="noopener noreferrer" href="'+url+'">'+L('前往邮箱验证 ↗','Open your inbox ↗')+'</a>':'')+link(L('返回登录','Back to login'),'login','quiet')+'</div></section>';}
function profileView(){const total={CNY:0,GBP:0};for(const r of data.records)for(const [currency,value]of Object.entries(r.costs||{}))total[currency]=(total[currency]||0)+value;const totals=Object.entries(total).filter(([,n])=>n).map(([c,n])=>new Intl.NumberFormat(lang==='en'?'en-GB':'zh-CN',{style:'currency',currency:c}).format(n)).join(' + ')||'—';return `<section>${cookingResume()}<h1 class="page-title">${L('我的小饭桌','My Little Table')}</h1>${accountNotice()}<div class="panel profile-panel"><div class="identity">${art(recipe('jiangsu-rice'),96)}<div><h2>${esc(profile?.display_name||L('饭团','Riceball'))}</h2><small>${profile?'ID · '+esc(profile.id.slice(0,8)):L('游客体验','Guest mode')}</small><p class="offline-indicator">${esc(!cloud.currentSession()?L('未登录，使用记录不会保存。','You’re not logged in. Your activity will not be saved.'):ui.cloudMessage|| (cloudReady?L('云端同步已启用','Cloud sync enabled'):L('保存在当前浏览器','Saved in this browser')))}</p></div></div><div class="stats"><div class="stat"><small>${L('完成一餐','Meals completed')}</small><strong>${data.records.length}</strong></div><div class="stat"><small>${L('私房菜单','Saved recipes')}</small><strong>${privateRecipes().length}</strong></div><div class="stat"><small>${L('累计花费','Recorded cost')}</small><strong>${esc(totals)}</strong></div></div><h2>${L('最近开饭','Recent meals')}</h2><div class="record-grid">${data.records.slice().reverse().slice(0,10).map(rec=>`<a href="#history/${esc(rec.id)}" class="record"><strong>${date(rec.completedAt)}</strong><small>${rec.recipes.map(r=>esc(title(r))).join(' / ')}</small><div class="record-art">${rec.recipes.slice(0,3).map(r=>art(r,125)).join('')}</div></a>`).join('')||`<div class="empty">${L('第一顿，等你开饭','Your first meal is waiting')}</div>`}</div><div class="profile-actions">${link(L('私房菜单','Private menu'),'today','secondary')}${link(L('创建食谱 ＋','Create recipe ＋'),'create','secondary')}${action(L('我的投稿','My submissions'),'my-posts','','quiet')}</div><div class="toolbar">${action(L('导出备份','Export backup'),'export','','quiet small-button')}<label class="button quiet small-button">${L('导入备份','Import backup')}<input id="import-file" type="file" accept="application/json,.json" hidden></label>${action(L('添加到手机桌面','Add to home screen'),'install-help','','quiet small-button')}${profile? action(L('刷新账号状态','Refresh account'),'refresh-account','','quiet small-button')+action(L('退出登录','Log out'),'logout','','quiet small-button'):link(L('邮箱登录 / 注册','Email login / sign up'),'login','quiet')}${profile?.is_admin?link(L('管理后台','Admin'),'admin','secondary'):''}</div></div></section>`;}
function date(value){return new Date(value).toLocaleString(lang==='en'?'en-GB':'zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function historyView(id){const r=data.records.find(r=>r.id===id);if(!r)return `<div class="empty">${L('还没有这条记录','Record not found')}</div>`;return `<section class="form-shell"><h1 class="page-title">${L('这顿饭的记录','A meal to remember')}</h1><div class="panel stack"><div class="record-art">${r.recipes.slice(0,3).map(x=>art(x,160)).join('')}</div><h2>${date(r.completedAt)}</h2><ul class="timeline">${[[r.viewedAt,L('看食谱','Explored recipes')],[r.plannedAt,L('安排一餐','Planned a meal')],[r.groceriesAt||r.completedAt,L('采购完成','Groceries ready')],[r.cookingAt,L('开始做菜','Started cooking')],[r.completionVersion>=6?r.completedAt:null,L('全部出餐','All served')]].filter(([t])=>t).map(([t,text])=>'<li>✓ <small>'+date(t)+'</small> '+text+'</li>').join('')}</ul>${r.recipes.map(x=>`<div class="row between"><a href="#recipe/${encodeURIComponent(x.id)}">${esc(title(x))}</a><span>${r.prices[x.id]?new Intl.NumberFormat(lang==='en'?'en-GB':'zh-CN',{style:'currency',currency:r.prices[x.id].currency}).format(r.prices[x.id].value):'—'}</span></div>`).join('')}<details class="pantry"><summary>${L('买菜清单','Shopping list')}</summary><p>${r.items.map(i=>esc(tr(i.name))+' '+esc(tr(i.amount))+' · '+(i.status==='owned'?L('已有','Already had'):L('已买','Bought'))).join('<br>')}</p></details>${cookingHistory(r,cookingHelpers())}${action(L('再吃一次 ＋','Have it again ＋'),'repeat',id)}${link(L('返回个人主页','Back to my kitchen'),'profile','quiet')}</div></section>`;}
function editorView(id){const existing=id?recipe(id):null;const r=ui.editor?.id===id?ui.editor:existing||{title:'',cuisine:'家常菜',category:'蔬菜',servings:2,time:20,ingredients:[],steps:[],tags:[]};ui.editor={...r,id};ui.editorImage=r.image||null;ui.editorIcon=r.icon||r.id||'custom-mushroom-pasta';return `<section class="form-shell"><h1 class="page-title">${id?L('编辑食谱','Edit recipe'):L('创建食谱','Create recipe')}</h1><form id="recipe-form" class="panel"><div class="form-grid"><label class="field wide">${L('菜名','Recipe name')}<input name="title" required maxlength="100" value="${esc(r.title)}"></label><label class="field wide">${L('英文菜名（选填）','English name (optional)')}<input name="titleEn" maxlength="100" value="${esc(r.en?.title||'')}"></label><label class="field">${L('地域菜系','Cuisine')}<select name="cuisine">${cuisines.slice(1).map(c=>`<option value="${c}" ${r.cuisine===c?'selected':''}>${esc(tr(c))}</option>`).join('')}</select></label><label class="field">${L('主要食材','Main ingredient')}<select name="category">${categories.slice(1).map(c=>`<option value="${c}" ${r.category===c?'selected':''}>${esc(tr(c))}</option>`).join('')}</select></label><div class="field wide">${L('分类（可多选）','Tags (choose any)')}<div class="row">${['增肌减脂','早饭'].map(t=>`<label><input name="tags" type="checkbox" value="${t}" ${r.tags?.includes(t)?'checked':''}> ${esc(tr(t))}</label>`).join('')}</div></div><label class="field">${L('份量','Servings')}<input name="servings" type="number" required min="1" max="30" value="${r.servings||2}"></label><label class="field">${L('用时（分钟）','Time (minutes)')}<input name="time" type="number" required min="1" max="1440" value="${r.time||20}"></label><div class="visual-picker wide"><div id="editor-visual">${r.image&&safeImage(r.image)?`<img class="photo-cover" src="${esc(r.image)}" width="150" height="150" alt="">`:art({...r,icon:ui.editorIcon},150)}</div><div class="stack">${action(L('选择图标','Choose icon'),'choose-icon','','secondary')}<label class="button quiet">${L('添加图片','Add photo')}<input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp" hidden></label></div></div><label class="field wide">${L('食材与用量（每行一项）','Ingredients & quantities (one per line)')}<textarea name="ingredients" required maxlength="8000" placeholder="${L('蘑菇 200克\n意大利面 180克','Mushrooms 200g\nPasta 180g')}">${esc((r.ingredients||[]).join('\n'))}</textarea></label><label class="field wide">${L('做法（每行一步）','Method (one step per line)')}<textarea name="steps" required maxlength="16000">${esc((r.steps||[]).join('\n'))}</textarea></label><label class="field wide">${L('英文食材与步骤（选填）','English ingredients & method (optional)')}<details><summary>${L('编辑英文内容','Edit English content')}</summary><div class="stack"><textarea name="ingredientsEn" placeholder="Ingredients">${esc((r.en?.ingredients||[]).join('\n'))}</textarea><textarea name="stepsEn" placeholder="Method">${esc((r.en?.steps||[]).join('\n'))}</textarea></div></details></label><label class="field">${L('热量（kcal / 份，选填）','Energy (kcal / serving, optional)')}<input name="kcal" type="number" min="0" max="10000" value="${r.nutrition?.kcal??''}"></label><label class="field">${L('蛋白质（g / 份，选填）','Protein (g / serving, optional)')}<input name="protein" type="number" min="0" max="1000" step="0.1" value="${r.nutrition?.protein??''}"></label><label class="field wide">${L('备注（选填）','Notes (optional)')}<textarea name="note" maxlength="4000">${esc(r.note||'')}</textarea></label></div><div class="form-actions">${link(L('取消','Cancel'),'today','quiet')}<button type="submit" class="button primary">${L('保存到私房菜单','Save to private menu')}</button></div></form></section>`;}
function authView(view){const register=view==='register',recover=view==='forgot',reset=view==='reset-password';return `<section class="auth-shell"><div class="panel">${art(recipe('jiangsu-rice')||{id:'jiangsu-rice'},180)}<h1>${reset?L('设置新密码','Set a new password'):recover?L('找回密码','Reset password'):register?L('加入小饭桌','Join Little Table'):L('欢迎回来','Welcome back')}</h1>${!recover&&!reset?`<div class="auth-tabs"><a href="#login" class="${!register?'active':''}">${L('登录','Log in')}</a><a href="#register" class="${register?'active':''}">${L('注册','Sign up')}</a></div>`:''}<form id="auth-form" data-mode="${view}">${register?`<label class="field">${L('昵称','Nickname')}<input name="name" required maxlength="40" autocomplete="nickname"></label>`:''}${!reset?`<label class="field">${L('邮箱','Email')}<input name="email" type="email" required autocomplete="email" maxlength="254"></label>`:''}${!recover?`<label class="field">${L('密码（至少8位）','Password (at least 8 characters)')}<input name="password" type="password" required minlength="8" autocomplete="${register||reset?'new-password':'current-password'}"></label>`:''}<p class="form-feedback" role="status" id="auth-feedback"></p><button class="button primary" type="submit">${register?L('注册并申请内测','Sign up & request access'):recover?L('发送重置邮件','Send reset email'):reset?L('保存密码','Save password'):L('登录','Log in')}</button></form>${register?`<p class="auth-note">${L('注册后请先完成邮箱验证。','Verify your email after signing up.')}</p>`:''}${!cloud.cloudConfigured?`<p class="auth-note">${L('账号服务暂未连接，请稍后再试。','Account access is temporarily unavailable. Please try again later.')}</p>`:''}<div class="row between">${link(L('返回首页','Back to home'),'home','quiet small-button')}${!register&&!reset?`<a class="small-button" href="#forgot">${L('忘记密码','Forgot password?')}</a>`:''}</div></div></section>`;}
function adminView(){if(!profile?.is_admin)return `<div class="empty">${L('仅管理员可访问','Administrator access required')}</div>`;return `<section><h1 class="page-title">${L('管理后台','Administration')}</h1><div class="panel stack"><h2>${L('用户审核','Member approval')}</h2><div id="admin-users" class="admin-list">${ui.adminUsers.map(u=>`<div class="admin-row"><div><strong>${esc(u.display_name||u.email)}</strong><p><small>${esc(u.email)} · ${esc(u.status)}</small></p></div><div class="row">${['approved','rejected','suspended'].map(s=>action(s==='approved'?L('通过','Approve'):s==='rejected'?L('拒绝','Reject'):L('停用','Suspend'),'admin-user',u.id,'secondary small-button',`data-status="${s}" ${u.id===profile.id?'disabled':''}`)).join('')}</div></div>`).join('')||'<small>'+L('暂无待审用户','No users to review')+'</small>'}</div><h2>${L('投稿审核','Recipe submissions')}</h2><div class="admin-list">${ui.adminPosts.map(s=>`<div class="admin-row"><div><strong>${esc(lang==='en'?s.recipe.en?.title||s.recipe.title:s.recipe.title)}</strong><p><small>${esc(s.author_id.slice(0,8))} · ${esc(s.status)}</small></p></div><div class="row">${action(L('查看','View'),'review',s.id,'quiet small-button')}${action(L('通过并公开','Approve & publish'),'admin-post',s.id,'secondary small-button','data-status="approved"')}${action(L('退回','Return'),'admin-post',s.id,'quiet small-button','data-status="rejected"')}</div></div>`).join('')||'<small>'+L('暂无投稿','No submissions')+'</small>'}</div></div></section>`;}
function render(){const {view,id}=getRoute();const menuScroll=view==='today'&&$('#main').dataset.view==='today'?$('.menu-list')?.scrollTop||0:0;header(view);let markup;if(!publicViews.has(view)&&!canUseMembers())markup=memberGate();else if(view==='rights')markup=rightsView();else if(view==='library')markup=library();else if(view==='today')markup=today();else if(view==='shopping')markup=shopping();else if(view==='cooking')markup=cookingView(data.cooking,data.cooking?.recordId?data.records.find(r=>r.id===data.cooking.recordId):null,cookingHelpers());else if(view==='profile')markup=profileView();else if(view==='recipe')markup=detail(recipe(id));else if(view==='history')markup=historyView(id);else if(view==='create'||view==='edit')markup=editorView(view==='edit'?id:'');else if(view==='verify-email')markup=verifyEmailView();else if(['login','register','forgot','reset-password'].includes(view))markup=authView(view);else if(view==='admin')markup=adminView();else markup=home();$('#main').innerHTML=markup;$('#main').dataset.view=view;document.body.dataset.view=view;if(view==='today'&&canUseMembers()&&$('.menu-list'))$('.menu-list').scrollTop=menuScroll;if(view==='library'&&canUseMembers())updateCards();if(view==='shopping'&&canUseMembers())updateMapLinks();observeArt();if(view==='cooking'&&canUseMembers())revealCookTicket(data.cooking?.activeId);}
function startJourney(viewedId){if(!data.journey)data.journey={id:crypto.randomUUID(),viewedAt:new Date().toISOString(),viewedIds:[]};if(viewedId&&!data.journey.viewedIds.includes(viewedId))data.journey.viewedIds.push(viewedId);}
function planRecipe(id){if(cookingActive()){toast(L('这餐正在做，完成后再调整菜单','Finish the current meal before changing its menu'));return;}data.cooking=null;if(data.plan[id])delete data.plan[id];else{startJourney(id);data.journey.plannedAt=data.journey.plannedAt||new Date().toISOString();data.plan[id]=1;}persist();}
function captureEditor(){const form=$('#recipe-form');if(!form)return;const f=new FormData(form);ui.editor={...ui.editor,title:f.get('title'),cuisine:f.get('cuisine'),category:f.get('category'),servings:Number(f.get('servings')),time:Number(f.get('time')),ingredients:lines(f.get('ingredients')),steps:lines(f.get('steps')),tags:f.getAll('tags'),image:ui.editorImage,icon:ui.editorIcon,note:f.get('note'),en:{title:f.get('titleEn'),ingredients:lines(f.get('ingredientsEn')),steps:lines(f.get('stepsEn'))},nutrition:f.get('kcal')!==''?{kcal:Number(f.get('kcal')),protein:Number(f.get('protein')||0),estimated:true}:null};}
function lines(value){return String(value||'').split('\n').map(s=>s.trim()).filter(Boolean);}
function openDialog(markup){$('#dialog').innerHTML=`<button class="dialog-close small-button" data-action="close" aria-label="${L('关闭','Close')}">×</button>`+markup;$('#dialog').showModal();observeArt();}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function cookingHelpers(){return {L,esc,art,title,localized,action,link};}
function cookingActive(){return !!data.cooking?.recipes?.length;}
function cookingResume(){return cookingActive()?'<div class="cooking-resume"><span>'+L('这餐还在做','A meal is in progress')+'</span>'+link(L('继续做菜 →','Continue cooking →'),'cooking','secondary small-button')+'</div>':'';}
function completion(){
 if(cookingActive()){navigate('cooking');return;}
 const items=listItems(),selected=planned();if(!selected.length||items.length&&!shoppingComplete(items,data.checks))return;
 const prices=Object.fromEntries(selected.filter(r=>data.prices[r.id]).map(r=>[r.id,data.prices[r.id]]));
 data.cooking=beginCooking({recipes:selected,plan:{...data.plan},prices,journey:data.journey||{},items:items.map(i=>({name:i.name,amount:i.amount,status:statusFor(i,data.checks)}))});persist();navigate('cooking');
}
function serveDish(id){if(!cookingActive()||busy)return;data.cooking=serveTicket(data.cooking,id);if(allServed(data.cooking)){
 const record=finishCooking(data.cooking);if(!data.records.some(r=>r.id===record.id))data.records.push(record);
 data.cooking={recordId:record.id};data.plan={};data.checks={};data.journey=null;
 }persist();render();}
function revealCookTicket(id){const track=$('.ticket-track'),ticket=[...document.querySelectorAll('.cook-ticket')].find(n=>n.dataset.ticket===id);if(!track||!ticket)return;const a=track.getBoundingClientRect(),b=ticket.getBoundingClientRect();if(b.left<a.left)track.scrollLeft-=a.left-b.left;else if(b.right>a.right)track.scrollLeft+=b.right-a.right;}
function renderCookingTicket(id){const scroll=$('.ticket-track')?.scrollLeft||0;const detailScroll=$('.cook-detail-scroll')?.scrollTop||0;render();if($('.ticket-track'))$('.ticket-track').scrollLeft=scroll;if($('.cook-detail-scroll'))$('.cook-detail-scroll').scrollTop=detailScroll;revealCookTicket(id);}
async function account(){cloudReady=false;memberVerified=false;catalogLoaded=false;const session=cloud.currentSession();if(!session){profile=null;activeKey='guest';await loadMemberCatalog();return;}profile=await cloud.getProfile();activeKey=session.user.id;data=normalizeData(read('little-table:'+activeKey,freshState()));if(profile)write('little-table-profile:'+activeKey,{id:profile.id,display_name:profile.display_name,status:profile.status});if(profile?.status==='approved'&&cloud.currentSession()?.user?.email_confirmed_at){await loadMemberCatalog();const dirty=read('little-table-dirty:'+activeKey,false),remote=await cloud.loadPrivate();if(remote&&!dirty)data=normalizeData(remote);cloudReady=true;memberVerified=true;write('little-table:'+activeKey,data);ui.cloudMessage=L('已同步','Synced');if(dirty)await syncCloud();}else ui.cloudMessage='';}
async function refreshPublic(){if(!cloud.cloudConfigured||!memberVerified){publicRecipes=[];counts={};return;}try{const [rows,popular]=await Promise.all([cloud.rpc('published_recipes'),cloud.rpc('recipe_counts')]);publicRecipes=(rows||[]).map(row=>({...row.recipe,id:row.id,contributor:row.contributor,createdAt:row.created_at,custom:false,public:true}));counts=Object.fromEntries((popular||[]).map(r=>[r.recipe_id,Number(r.total)]));}catch{}}
async function adminLoad(){if(!profile?.is_admin)return;[ui.adminUsers,ui.adminPosts]=await Promise.all([cloud.db('profiles?select=id,email,display_name,status,is_admin&order=created_at.desc'),cloud.db('submissions?select=*&order=created_at.desc')]);if(getRoute().view==='admin')render();}
async function saveFavourite(id){const index=data.saved.indexOf(id);if(index<0)data.saved.push(id);else data.saved.splice(index,1);persist();render();if(cloudReady){try{await cloud.db(index<0?'recipe_saves?on_conflict=user_id,recipe_id':'recipe_saves?user_id=eq.'+profile.id+'&recipe_id=eq.'+encodeURIComponent(id),index<0?{method:'POST',prefer:'resolution=merge-duplicates',body:{user_id:profile.id,recipe_id:id}}:{method:'DELETE'});await refreshPublic();}catch{toast(L('收藏已保存在本机，统计暂未同步','Saved on this device; count not synced'));}}}
document.addEventListener('click',async event=>{const trigger=event.target.closest('[data-action]');if(!canUseMembers()&&event.target.closest('[data-action],[data-filter],[data-owned]')&&(!trigger||!publicActions.has(trigger.dataset.action))){render();return;}const f=event.target.closest('[data-filter]');if(f){ui[f.dataset.filter]=f.dataset.value;render();return;}const owned=event.target.closest('[data-owned]');if(owned){const item=listItems().find(i=>i.id===owned.dataset.owned);data.checks=setItemStatus(data.checks,item,statusFor(item,data.checks)==='owned'?'pending':'owned');persist();render();return;}const b=event.target.closest('[data-action]');if(!b)return;const {action:a,id}=b.dataset;
 try{
 if(a==='language'){captureEditor();lang=lang==='zh'?'en':'zh';write('shiguang-language',lang);const address=new URL(location.href);address.searchParams.set('lang',lang);history.replaceState(null,'',address);render();return;}
 if(a==='close'){$('#dialog').close();return;}
 if(a==='save'){await saveFavourite(id);return;}
 if(a==='plan'){planRecipe(id);render();return;}
 if(a==='add-table'){if(!data.saved.includes(id)&&!recipe(id).custom)data.saved.push(id);if(!data.plan[id])planRecipe(id);navigate('today');return;}
 if(a==='clear-plan'){if(cookingActive()){navigate('cooking');return;}data.cooking=null;data.plan={};data.journey=null;persist();render();return;}
 if(a==='random'){if(cookingActive()){navigate('cooking');return;}const available=privateRecipes().filter(r=>!data.plan[r.id]);if(!available.length){toast(L('先收藏喜欢的菜','Save some favourites first'));return;}for(const r of available.sort(()=>Math.random()-.5).slice(0,Number($('#random-count').value)))planRecipe(r.id);render();return;}
 if(a==='matching'){ui.matching=!ui.matching;render();return;}
 if(a==='price'){const p=data.prices[id];openDialog(`<h2>${L('记录价格','Record cost')}</h2><p>${esc(title(recipe(id)))}</p><form id="price-form" data-id="${esc(id)}"><label class="field">${L('货币','Currency')}<select name="currency"><option value="CNY" ${p?.currency==='CNY'?'selected':''}>CNY ¥</option><option value="GBP" ${(p?.currency|| (lang==='en'?'GBP':'CNY'))==='GBP'?'selected':''}>GBP £</option></select></label><label class="field">${L('本份食材实际花费','Actual ingredient cost for this recipe')}<input name="amount" type="number" min="0" max="100000" step="0.01" required value="${p?.value??''}"></label><button class="button primary">${L('保存价格','Save cost')}</button></form>`);return;}
 if(a==='choose-icon'){captureEditor();openDialog(`<h2>${L('选择图标','Choose an icon')}</h2><div class="icon-choices">${artAssets.map(x=>`<button class="icon-choice" data-action="set-icon" data-id="${x.id}" aria-label="${esc(tr(x.name))}">${art({icon:x.id})}</button>`).join('')}</div>`);return;}
 if(a==='set-icon'){ui.editorIcon=id;ui.editor.icon=id;ui.editor.image=null;ui.editorImage=null;$('#dialog').close();$('#editor-visual').innerHTML=art({icon:id},150);observeArt();return;}
 if(a==='complete'){completion();return;}
 if(a==='cook-select'){if(cookingActive()&&data.cooking.order.includes(id)){data.cooking.activeId=id;persist();renderCookingTicket(id);$('.cook-detail-scroll')?.scrollTo({top:0});}else if(data.cooking?.recordId){navigate('history/'+data.cooking.recordId);}return;}
 if(a==='cook-move'){if(cookingActive()){data.cooking=moveTicket(data.cooking,id,Number(b.dataset.direction));persist();renderCookingTicket(id);}return;}
 if(a==='cook-serve'){serveDish(id);return;}
 if(a==='cook-remove-photo'){if(cookingActive()){delete data.cooking.photos[id];persist();renderCookingTicket(id);}return;}
 if(a==='repeat'){if(cookingActive()){navigate('cooking');return;}data.cooking=null;const record=data.records.find(r=>r.id===id);if(!record)return;data.plan=Object.fromEntries(Object.entries(record.plan).filter(([key])=>recipe(key)));data.checks={};data.journey={id:crypto.randomUUID(),viewedAt:new Date().toISOString(),plannedAt:new Date().toISOString()};persist();navigate('today');return;}
 if(a==='export'){download('little-table-backup-'+new Date().toISOString().slice(0,10)+'.json',{version:6,exportedAt:new Date().toISOString(),...data});return;}
 if(a==='delete-recipe'){if(cookingActive()&&data.cooking.order.includes(id)){toast(L('完成这餐后再删除食谱','Finish this meal before deleting its recipe'));return;}if(confirm(L('删除这道个人食谱？','Delete this personal recipe?'))){data.custom=data.custom.filter(r=>r.id!==id);data.saved=data.saved.filter(x=>x!==id);delete data.plan[id];persist();navigate('today');}return;}
 if(a==='submit-recipe'){if(!cloudReady){toast(L('投稿需要已审核通过的邮箱账号','An approved email account is required to submit'));navigate(profile?'profile':'login');return;}const r=recipe(id);openDialog(`<h2>${L('投稿食谱','Submit recipe')}</h2><p>${esc(title(r))}</p><p class="auth-note">${L('审核通过后公开，并显示你的贡献者ID。','After approval, the recipe becomes public with your contributor ID.')}</p><label class="row"><input id="consent" type="checkbox">${L('我确认可以公开分享','I confirm I can share this publicly')}</label><br>${action(L('提交审核','Submit for review'),'send-submission',id)}`);return;}
 if(a==='send-submission'){if(!$('#consent').checked)return;const r=recipe(id),sid=crypto.randomUUID();await cloud.db('submissions',{method:'POST',body:{id:sid,author_id:profile.id,recipe:r,status:'pending'}});data.submissions.push({id:sid,recipeId:id,status:'pending',createdAt:new Date().toISOString()});persist();$('#dialog').close();toast(L('已提交，等待审核','Submitted for review'));return;}
 if(a==='my-posts'){let posts=data.submissions;if(cloudReady)posts=await cloud.db('submissions?author_id=eq.'+profile.id+'&select=id,recipe,status,created_at');openDialog(`<h2>${L('我的投稿','My submissions')}</h2><div class="stack">${posts.map(s=>`<div><strong>${esc(s.recipe?(lang==='en'?s.recipe.en?.title||s.recipe.title:s.recipe.title):title(recipe(s.recipeId)||{title:''}))}</strong><p>${esc(({pending:L('待审核','Pending'),approved:L('已公开','Published'),rejected:L('已退回','Returned')})[s.status]||s.status)}</p></div>`).join('')||L('暂无投稿','No submissions yet')}</div>`);return;}
 if(a==='logout'){await cloud.signOut();memberVerified=false;catalogLoaded=false;seeds=[];newRecipes=[];kitchen={};publicRecipes=[];counts={};setTranslations([]);profile=null;cloudReady=false;activeKey='guest';data=freshState();await loadMemberCatalog();render();return;}
 if(a==='refresh-account'){accountChecking=true;render();try{await account();await refreshPublic();}finally{accountChecking=false;render();}return;}
 if(a==='admin-user'){b.disabled=true;try{await cloud.rpc('review_user',{target_id:id,new_status:b.dataset.status});}catch(error){toast(actionError(error,lang));return;}finally{b.disabled=false;}try{await adminLoad();toast(L('审核已更新','Review updated'));}catch{toast(L('审核已提交，但列表刷新失败，请刷新页面核对。','Review submitted, but the list could not refresh. Reload to confirm.'));}return;}
 if(a==='review'){const s=ui.adminPosts.find(x=>x.id===id);openDialog(`<h2>${esc(s.recipe.title)}</h2><h3>${L('食材','Ingredients')}</h3><p>${s.recipe.ingredients.map(esc).join('<br>')}</p><h3>${L('做法','Method')}</h3><ol>${s.recipe.steps.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol>`);return;}
 if(a==='admin-post'){await cloud.rpc('review_submission',{target_id:id,new_status:b.dataset.status});await adminLoad();await refreshPublic();toast(L('已更新','Updated'));return;}
 if(a==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;render();return;}
 if(a==='install-help'){openDialog(`<h2>${L('添加到手机桌面','Add to home screen')}</h2><p>${L('iPhone：用 Safari 打开，点分享，再选择“添加到主屏幕”。Android：打开浏览器菜单，选择“安装应用”或“添加到主屏幕”。','iPhone: open in Safari, tap Share, then Add to Home Screen. Android: open your browser menu and choose Install app or Add to Home screen.')}</p>`);return;}
 }catch(error){console.error(error);toast(actionError(error,lang));}
});
let draggedTicket=null;
document.addEventListener('dragstart',e=>{const ticket=e.target.closest('.cook-ticket[draggable="true"]');if(!ticket)return;draggedTicket=ticket.dataset.ticket;e.dataTransfer.setData('text/plain',draggedTicket);e.dataTransfer.effectAllowed='move';ticket.classList.add('dragging');});
document.addEventListener('dragover',e=>{const t=e.target.closest('.cook-ticket[draggable="true"]');if(t&&draggedTicket){e.preventDefault();e.dataTransfer.dropEffect='move';t.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>e.target.closest('.cook-ticket')?.classList.remove('drag-over'));
document.addEventListener('drop',e=>{const t=e.target.closest('.cook-ticket[draggable="true"]');if(!t||!draggedTicket||!cookingActive())return;e.preventDefault();data.cooking=placeTicket(data.cooking,draggedTicket,t.dataset.ticket);draggedTicket=null;persist();renderCookingTicket();});
document.addEventListener('dragend',()=>{draggedTicket=null;document.querySelectorAll('.dragging,.drag-over').forEach(n=>n.classList.remove('dragging','drag-over'));});
document.addEventListener('input',e=>{if(e.target.id==='search'){ui.query=e.target.value;updateCards();}if(e.target.id==='pantry'){ui.pantry=e.target.value;updateCards();}});
document.addEventListener('change',async e=>{if(!canUseMembers())return;const el=e.target;try{if(el.id==='sort'){ui.sort=el.value;updateCards();}if(el.id==='extra'){ui.extra=Number(el.value);updateCards();}if(el.id==='map-provider'){write('little-table-map',el.value);updateMapLinks();}if(el.id==='bulk'){data.checks=purchaseAll(listItems(),data.checks,!el.checked);persist();render();}if(el.dataset.check){const i=listItems().find(i=>i.id===el.dataset.check);data.checks=setItemStatus(data.checks,i,el.checked?'bought':'pending');persist();render();}if(el.dataset.portion){if(cookingActive()){toast(L('这餐正在做，份量已固定','This meal is cooking; portions are fixed'));render();return;}const n=Number(el.value);if(n>=.5&&n<=20){data.plan[el.dataset.portion]=n;persist();render();}}if(el.classList.contains('cook-photo-input')&&el.files[0]){
 const owner=activeKey,mealId=data.cooking?.id,id=el.dataset.id;if(busy||!cookingActive()||!data.cooking.order.includes(id))return;busy=true;
 document.querySelectorAll('[data-action="cook-serve"]').forEach(b=>b.disabled=true);
 try{const photo=await compressMealPhoto(el.files[0]);if(activeKey!==owner||data.cooking?.id!==mealId)return;
 const next=structuredClone(data);next.cooking.photos[id]=photo;
 if(JSON.stringify(next).length>2400000||(activeKey!=='guest'&&!write('little-table:'+activeKey,next))){toast(L('照片空间不足，请先导出备份','Photo storage is full. Export a backup first.'));return;}
 data=next;persist();if(getRoute().view==='cooking')renderCookingTicket(id);
 }finally{busy=false;document.querySelectorAll('[data-action="cook-serve"]').forEach(b=>b.disabled=false);el.value='';}return;
 }if(el.id==='photo-file'&&el.files[0]){captureEditor();const file=el.files[0];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5e6)throw Error('IMAGE');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height));canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();ui.editorImage=canvas.toDataURL('image/jpeg',.8);ui.editor.image=ui.editorImage;$('#editor-visual').innerHTML=`<img class="photo-cover" width="150" height="150" src="${ui.editorImage}" alt="">`;}if(el.id==='import-file'&&el.files[0]){const file=el.files[0];if(file.size>5e6)throw Error('FILE');const value=JSON.parse(await file.text());const imported=Array.isArray(value)?value:value.custom||value.recipes;if(!Array.isArray(imported))throw Error('FILE');const added=imported.map(r=>{validateRecipe(r);return {...r,id:r.id&&String(r.id).startsWith('custom-')?r.id:'custom-'+crypto.randomUUID(),custom:true,image:safeImage(r.image),icon:artAssets.some(a=>a.id===r.icon)?r.icon:undefined};});for(const r of added){const index=data.custom.findIndex(x=>x.id===r.id);if(index<0)data.custom.push(r);else data.custom[index]=r;if(!data.saved.includes(r.id))data.saved.push(r.id);}if(value.version===5||value.version===6){for(const key of ['records','submissions'])if(Array.isArray(value[key])){const map=new Map([...data[key],...value[key]].map(r=>[r.id,r]));data[key]=[...map.values()];}if(!cookingActive()&&value.cooking){data.cooking=normalizeCooking(value.cooking);if(data.cooking?.recipes){data.plan={...data.cooking.plan};data.journey={id:data.cooking.id,viewedAt:data.cooking.viewedAt,plannedAt:data.cooking.plannedAt};}}if(value.prices&&typeof value.prices==='object')Object.assign(data.prices,value.prices);if(Array.isArray(value.saved))data.saved=[...new Set([...data.saved,...value.saved.filter(id=>recipe(id))])];}persist();render();toast(L('已导入','Imported'));}}catch{toast(L('文件无效，请检查格式或使用小于5MB的图片/JSON','Invalid file. Check the format and use an image or JSON under 5MB.'));}});
document.addEventListener('submit',async e=>{const form=e.target;e.preventDefault();if(form.id!=='auth-form'&&!canUseMembers()){render();return;}if(form.id==='recipe-form'){captureEditor();try{const draft=validateRecipe(ui.editor),old=recipe(draft.id),id=old?.custom?old.id:'custom-'+crypto.randomUUID();const r={...draft,id,custom:true,createdAt:old?.createdAt||new Date().toISOString(),image:safeImage(ui.editorImage),icon:ui.editorIcon,size:old?.size||'M',en:ui.editor.en};const index=data.custom.findIndex(x=>x.id===id);if(index<0)data.custom.push(r);else data.custom[index]=r;if(!data.saved.includes(id))data.saved.push(id);ui.editor=null;persist();navigate('recipe/'+id);}catch{toast(L('请填写名称、食材、做法和有效的用时','Enter a name, ingredients, method and valid cooking time'));}return;}if(form.id==='price-form'){const f=new FormData(form),value=Number(f.get('amount'));if(value>=0&&value<=100000){data.prices[form.dataset.id]={currency:f.get('currency'),value,updatedAt:new Date().toISOString()};persist();$('#dialog').close();render();}return;}if(form.id==='auth-form'){const feedback=$('#auth-feedback'),submit=form.querySelector('button[type=submit]');if(!cloud.cloudConfigured){feedback.textContent=L('邮箱服务尚未配置，暂不能注册或登录。','Email access has not been configured yet.');return;}const f=new FormData(form),mode=form.dataset.mode;submit.disabled=true;try{if(mode==='register'){await cloud.signUp(f.get('email'),f.get('password'),f.get('name'));ui.verificationEmail=String(f.get('email')).trim();try{sessionStorage.setItem('little-table-verification-email',ui.verificationEmail);}catch{}form.reset();navigate('verify-email');}else if(mode==='forgot'){await cloud.passwordEmail(f.get('email'));feedback.textContent=L('如该邮箱可用，重置邮件将发送给你。','If the email is eligible, a reset email will be sent.');}else if(mode==='reset-password'){await cloud.resetPassword(f.get('password'));await account();navigate('profile');}else {await cloud.signIn(f.get('email'),f.get('password'));await account();await refreshPublic();navigate('profile');}}catch(error){if(error.code==='email_not_confirmed'||/Email not confirmed/i.test(error.message)){ui.verificationEmail=String(f.get('email')||'').trim();try{sessionStorage.setItem('little-table-verification-email',ui.verificationEmail);}catch{}navigate('verify-email');}else feedback.textContent=L('未能完成，请检查邮箱、密码或网络后重试。','Could not complete this request. Check your email, password and connection.');}finally{submit.disabled=false;}}});
window.addEventListener('hashchange',()=>{const r=getRoute();if(r.view==='recipe'&&canUseMembers()){startJourney(r.id);persist();}if(r.view!=='create'&&r.view!=='edit')ui.editor=null;render();window.scrollTo({top:0});if(r.view==='admin')adminLoad().catch(()=>toast(L('无法加载管理数据','Could not load administration data')));});
window.addEventListener('storage',event=>{if(event.key==='little-table-session'&&event.newValue&&getRoute().view==='verify-email')location.reload();});
window.addEventListener('resize',()=>{if(getRoute().view==='cooking')revealCookTicket(data.cooking?.activeId);});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;header(getRoute().view);});window.addEventListener('online',()=>{if(cloud.cloudConfigured&&cloud.currentSession()&&!cloudReady)cloud.initializeAuth().then(account).then(render).catch(()=>{});else syncCloud();refreshPublic();});
render();
if(cloud.cloudConfigured)cloud.initializeAuth().then(account).then(refreshPublic).then(()=>{accountChecking=false;if(getRoute().view==='verify-email'&&profile&&cloud.currentSession()?.user?.email_confirmed_at&&cloud.currentSession().user.email?.toLowerCase()===ui.verificationEmail.toLowerCase())navigate('profile');else render();if(getRoute().view==='admin')return adminLoad();}).catch(()=>{accountChecking=false;memberVerified=false;ui.cloudMessage=L('无法连接账号服务，请联网后刷新账号状态。','Could not reach the account service. Connect and refresh your account.');render();toast(ui.cloudMessage);});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
